use dedaliano_engine::{certify,types::*};
use serde_json::json;
fn main(){
let args:Vec<String>=std::env::args().collect();
let input:SolverInput3D=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();
let result=certify::certify_linear_3d_full(&input);
std::fs::write(&args[2],serde_json::to_vec_pretty(&result).unwrap()).unwrap();
let bytes=std::fs::read(&args[3]).unwrap();
let plastic:PlasticInput3D=serde_json::from_slice(&bytes[2..]).unwrap();
let model=certify::plastic_3d::build_model_3d(&plastic).unwrap();
let work=certify::plastic_3d::lp_work(&model);
println!("work {work:?}; budget {:?}",work.check_engine_budget());
let start=std::time::Instant::now();
let result=certify::plastic_3d::certify_plastic_3d(&plastic);
std::fs::write(&args[4],serde_json::to_vec_pretty(&json!({"seconds":start.elapsed().as_secs_f64(),"result":result})).unwrap()).unwrap();
}

