import pathlib,json,re
p=pathlib.Path('engine/tests/metamorphic')
(p/'triage1113_probe.rs').write_text('''use serde_json::{Value,json};
#[test]
fn selected() {
    let dir = std::env::var("TRIAGE_DIR").unwrap();
    let specs: Value = serde_json::from_str(&std::fs::read_to_string(format!("{dir}/specs.json")).unwrap()).unwrap();
    for spec in specs.as_array().unwrap() {
        let n=spec["issue"].as_u64().unwrap();
        if let Ok(only)=std::env::var("TRIAGE_ONLY") { if !only.split(',').any(|s| s.parse::<u64>()==Ok(n)) {continue;} }
        std::env::set_var("TRIAGE_CURRENT", n.to_string());
        let text=std::fs::read_to_string(format!("{dir}/model-{n}.json")).unwrap();
        let v:Value=serde_json::from_str(&text).unwrap();
        let name=v["_nightly_name"].as_str().unwrap_or("replay");
        let ana=spec["analysis"].as_str().unwrap();
        let inv=spec["relation"].as_str().unwrap();
        let seed=spec["seed"].as_u64().unwrap();
        let t=crate::tally::Tally::default();
        match crate::corpus::parse(&text).unwrap() {
          crate::corpus::Model::D2(s)=> {
            let mut c=crate::case::Case2::new(name,s);
            if let Some(d)=v.get("_nightly_dens") {c.dens=serde_json::from_value(d.clone()).unwrap();}
            let a=crate::ana2::rows().into_iter().find(|a|a.name==ana).unwrap();
            let end=crate::INV_2D.iter().position(|s|*s==inv).unwrap()+1;
            crate::checks2::check_case(&crate::checks2::Ctx{tally:&t,rng_seed:seed},&c,&[a],&crate::INV_2D[..end]);
          }
          crate::corpus::Model::D3(s)=> {
            let mut c=crate::case::Case3::new(name,s);
            if let Some(d)=v.get("_nightly_dens") {c.dens=serde_json::from_value(d.clone()).unwrap();}
            let a=crate::ana3::rows().into_iter().find(|a|a.name==ana).unwrap();
            let end=crate::INV_3D.iter().position(|s|*s==inv).unwrap()+1;
            crate::checks3::check_case(&crate::checks3::Ctx{tally:&t,rng_seed:seed},&c,&[a],&crate::INV_3D[..end]);
          }
        }
        let result=t.replay_results();
        std::fs::write(format!("{dir}/observed-{n}.json"),serde_json::to_vec_pretty(&json!({"spec":spec,"results":result})).unwrap()).unwrap();
        println!("ISSUE {n}: {result}");
    }
}
''')
with (p/'main.rs').open('a') as f:f.write('\nmod triage1113_probe;\n')
for dim in [2,3]:
 f=p/f'checks{dim}.rs';s=f.read_text();(pathlib.Path('.triage-1113')/f'checks{dim}.rs').write_text(s)
 pos=f'fn run(a: &Ana{dim}, c: &Case{dim}) -> Result<Resp, String> {{'
 add='''
    if let (Ok(dir),Ok(n))=(std::env::var("TRIAGE_DIR"),std::env::var("TRIAGE_CURRENT")) {
        static COUNT:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
        let k=COUNT.fetch_add(1,std::sync::atomic::Ordering::Relaxed);
        std::fs::write(format!("{dir}/input-{n}-{k}.json"),serde_json::to_vec_pretty(&c.s).unwrap()).unwrap();
        let result=guarded(||(a.run)(c));
        std::fs::write(format!("{dir}/answer-{n}-{k}.txt"),format!("{result:?}")).unwrap();
    }
'''
 assert pos in s;f.write_text(s.replace(pos,pos+add))
specs=[]
for n in range(2011,2068):
