use dedaliano_engine::{certify, solver::{linear,corotational},types::*};
use serde_json::{Value,json};
fn main() {
    let args: Vec<String> = std::env::args().collect();
    for path in &args[1..] {
        let v: Value=serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
        let spatial=v["nodes"].as_object().unwrap().values().any(|n|n.get("y").is_some()&&n.get("z").is_some());
        let result=if spatial {
            let s:SolverInput3D=serde_json::from_value(v).unwrap();
            json!({"ssi":dedaliano_engine::solver::ssi::solve_ssi_3d(&dedaliano_engine::solver::ssi::SSIInput3D{solver:s.clone(),soil_springs:vec![],max_iter:50,tolerance:1e-10}),"linear":linear::solve_3d(&s),"certificate":certify::certify_linear_3d_full(&s),"corotational":corotational::solve_corotational_3d(&s,100,1e-10,4,false)})
        } else {
            let s:SolverInput=serde_json::from_value(v).unwrap();
            json!({"ssi":dedaliano_engine::solver::ssi::solve_ssi_2d(&dedaliano_engine::solver::ssi::SSIInput{solver:s.clone(),soil_springs:vec![],max_iter:50,tolerance:1e-10}),"linear":linear::solve_2d(&s),"certificate":certify::certify_linear_2d_full(&s),"corotational":corotational::solve_corotational_2d(&s,100,1e-10,4,false)})
        };
        std::fs::write(format!("{path}.answers"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();
    }
}

